#!/usr/bin/env bash
# Generic checks that keep site-specific data out of this public repository.
# Runs in CI and in the git hooks; needs no private list.
#
#  - no private (RFC 1918) or link-local IPv4 addresses anywhere:
#    examples must use 192.0.2.0/24, 198.51.100.0/24 or 203.0.113.0/24
#  - no site configuration files in the index
#  - no log files in the index (test data is generated by the tests)
set -euo pipefail
cd "$(git rev-parse --show-toplevel)"
bad=0

private_ip='(^|[^0-9.])(10\.[0-9]{1,3}|192\.168|172\.(1[6-9]|2[0-9]|3[01])|169\.254)\.[0-9]{1,3}\.[0-9]{1,3}([^0-9.]|$)'
if out=$(git grep -n -I -E "$private_ip" -- . ':!scripts/check-public.sh' ':!webui/go.sum'); then
    echo "check-public: private IP addresses found (use 192.0.2.x or 198.51.100.x in examples):" >&2
    printf '    %s\n' "$out" >&2
    bad=1
fi

if out=$(git ls-files | grep -E '(^|/)(inventory\.(yml|ini)|private-denylist\.txt|host_vars/|.*\.cred|htpasswd)$|group_vars/[^/]*[^e]\.yml$|(^|/)[^/]*\.env$' | grep -v -E '\.example\.(yml|env)$'); then
    echo "check-public: site configuration files must not be committed:" >&2
    printf '    %s\n' "$out" >&2
    bad=1
fi

if out=$(git ls-files | grep -E '\.(log|log\.[0-9]+|gz|zst|journal)$'); then
    echo "check-public: log files or archives must not be committed (tests generate their data):" >&2
    printf '    %s\n' "$out" >&2
    bad=1
fi

[ "$bad" -eq 0 ] || { echo "check-public: FAILED" >&2; exit 1; }
echo "check-public: ok"
